#include <iostream>
#include <string_view>
#include <array>

struct Phase {
    std::string_view name;
    std::string_view description;
};

int main() {
    constexpr std::array<Phase, 6> phases{{
        {"Edit", "Code typed in editor"},
        {"Preprocess", "Directives processed"},
        {"Compile", "Source translated to object code"},
        {"Link", "Objects bound with libraries"},
        {"Load", "Binary transferred to memory"},
        {"Execute", "CPU runs instructions"}
    }};

    std::cout << "C++ Six Execution Phases:\n";
    for (std::size_t i = 0; i < phases.size(); ++i) {
        std::cout << (i + 1) << ". " << phases[i].name << ": " << phases[i].description << "\n";
    }

    constexpr double baseEnergyJoules = 1500.0;
    constexpr double scaleFactor = 1.05;
    constexpr double safeThresholdJoules = 2000.0;
    double computedEnergy = baseEnergyJoules * scaleFactor;

    if (computedEnergy <= safeThresholdJoules) {
        std::cout << "Radiation dose safe: " << computedEnergy << " J\n";
    } else {
        std::cout << "Safety limit exceeded!\n";
    }

    return 0;
}

#include <iostream>
#include <string>
#include <sstream>
#include <vector>
#include <iomanip>

class BMICalculator {
private:
    double weightKg;
    double heightM;
public:
    BMICalculator(double weight, double height) : weightKg(weight), heightM(height) {}

    double calculate() const {
        if (heightM <= 0.0) return 0.0;
        return weightKg / (heightM * heightM);
    }

    std::string getCategory() const {
        double bmi = calculate();
        if (bmi < 18.5) return "Underweight";
        if (bmi < 25.0) return "Normal weight";
        if (bmi < 30.0) return "Overweight";
        return "Obese";
    }
};

std::string replaceWholeWord(const std::string& sentence, const std::string& target, const std::string& replacement) {
    std::istringstream stream(sentence);
    std::string token;
    std::string result;
    bool first = true;
    while (stream >> token) {
        if (token == target) {
            token = replacement;
        }
        if (!first) result += " ";
        result += token;
        first = false;
    }
    return result;
}

int main() {
    BMICalculator person(70.0, 1.75);
    std::cout << std::fixed << std::setprecision(1);
    std::cout << "BMI: " << person.calculate() << " (" << person.getCategory() << ")\n";

    std::string text = "the man and woman met";
    std::string neutralized = replaceWholeWord(text, "man", "person");
    std::cout << "Neutralized text: " << neutralized << "\n";

    return 0;
}
